package com.trampolim.api.hub;
import java.util.*;import java.time.*;
import static com.trampolim.api.radar.RadarModel.*;
import com.trampolim.api.radar.RadarBridge;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.beans.factory.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@RestController
@ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class HubCompanyInvites {
 private final JdbcTemplate jdbc;private final HubAccess access;private final HubService service;
 @Value("${app.frontend-url:http://localhost:5173}")private String frontend;
 public HubCompanyInvites(@Qualifier("empresasJdbcTemplate")JdbcTemplate jdbc,HubAccess access,HubService service){this.jdbc=jdbc;this.access=access;this.service=service;}
 public record Invite(String email){}public record Accept(String token){}
 @PostMapping("/api/empresas/hub/organizations/{id}/company-invites")@Transactional("empresasTransactionManager")public Map<String,Object> invite(@AuthenticationPrincipal String actor,@PathVariable long id,@RequestBody Invite input){access.require(actor,id,true);access.additionalWrite(id);String email=text(input==null?null:input.email(),180).toLowerCase(Locale.ROOT);if(!email.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))bad("Informe o e-mail do responsável empresarial.");jdbc.queryForObject("SELECT id FROM enterprise_organizations WHERE id=? FOR UPDATE",Long.class,id);if(jdbc.queryForObject("SELECT count(*) FROM hub_company_invites WHERE organization_id=? AND created_at>CURRENT_TIMESTAMP-INTERVAL '1 day'",Integer.class,id)>=100)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Limite diário de convites atingido.");String token=UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");jdbc.update("INSERT INTO hub_company_invites(organization_id,email,token_hash,expires_at) VALUES (?,?,?,CURRENT_TIMESTAMP+INTERVAL '7 days')",id,email,RadarBridge.hash(token));service.audit(id,actor,"HUB_COMPANY_INVITED");return Map.of("inviteUrl",frontend+"/?hubCompanyInvite="+token+"#empresas","email",email);}
 @GetMapping("/api/empresas/hub/company-invites/preview")public Map<String,Object> preview(@AuthenticationPrincipal String email,@RequestParam String token){if(token==null||!token.matches("[a-f0-9]{64}"))bad("Convite inválido.");return jdbc.queryForList("SELECT o.name AS institution_name,i.expires_at,(i.accepted_at IS NOT NULL) AS already_accepted FROM hub_company_invites i JOIN enterprise_organizations o ON o.id=i.organization_id WHERE i.token_hash=? AND LOWER(i.email)=LOWER(?) AND i.expires_at>CURRENT_TIMESTAMP AND o.status='ACTIVE' AND EXISTS(SELECT 1 FROM company_users u WHERE LOWER(u.email)=LOWER(?) AND u.email_verified=TRUE AND u.account_status='ACTIVE')",RadarBridge.hash(token),email,email).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Convite expirado, indisponível ou destinado a outro e-mail."));}
 @PostMapping("/api/empresas/hub/company-invites/accept")@Transactional("empresasTransactionManager")public Map<String,Object> accept(@AuthenticationPrincipal String email,@RequestBody Accept input){if(input==null||input.token()==null||!input.token().matches("[a-f0-9]{64}"))bad("Convite inválido.");var membership=jdbc.queryForList("SELECT m.company_id FROM company_members m JOIN company_users u ON u.id=m.user_id WHERE LOWER(u.email)=LOWER(?) AND u.email_verified=TRUE AND u.account_status='ACTIVE' AND m.role IN ('OWNER','ADMIN')",email);if(membership.isEmpty())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Entre como responsável ou administrador de uma empresa cadastrada em Empresas.");long company=((Number)membership.get(0).get("company_id")).longValue();var invites=jdbc.queryForList("SELECT i.* FROM hub_company_invites i JOIN enterprise_organizations o ON o.id=i.organization_id WHERE i.token_hash=? AND LOWER(i.email)=LOWER(?) AND i.expires_at>CURRENT_TIMESTAMP AND o.status='ACTIVE' FOR UPDATE OF i",RadarBridge.hash(input.token()),email);if(invites.isEmpty())bad("Convite expirado, indisponível ou de outro e-mail.");var invite=invites.get(0);if(invite.get("accepted_at")!=null){if(invite.get("accepted_company_id")==null||((Number)invite.get("accepted_company_id")).longValue()!=company)bad("Convite já utilizado.");return Map.of("status","PENDING_REVIEW");}long org=((Number)invite.get("organization_id")).longValue();jdbc.update("INSERT INTO enterprise_organization_companies(organization_id,company_id,relationship_type,status) VALUES (?,?,'ASSOCIATION_MEMBER','PENDING') ON CONFLICT(organization_id,company_id,relationship_type) DO NOTHING",org,company);jdbc.update("UPDATE hub_company_invites SET accepted_at=CURRENT_TIMESTAMP,accepted_company_id=? WHERE id=?",company,invite.get("id"));service.audit(org,email,"HUB_COMPANY_INVITE_ACCEPTED");return Map.of("status","PENDING_REVIEW","notice","Participação solicitada. A administração da Trampolim precisa aprovar o vínculo; nenhum dado privado foi compartilhado.");}
}
